CREATE TABLE dbo.student (
    roll_no INT PRIMARY KEY,
    is_present BIT NOT NULL,
    name NVARCHAR(100) NOT NULL
);

INSERT INTO dbo.student (roll_no, is_present, name)
VALUES (101, 1, 'Ravi'),
       (102, 1, 'Anita');

SELECT roll_no, is_present, name
FROM dbo.student
WHERE roll_no = 101;

BEGIN TRAN;
UPDATE dbo.student
SET name = 'Ravi Kumar'
WHERE roll_no = 101;
ROLLBACK;
